export function originalLotteryBingoIndex(weights,rangeInt){
 if(typeof rangeInt!=='function')throw new TypeError('Explicit integer range callback required');
 const total=weights.reduce((sum,value)=>sum+value,0),roll=rangeInt(0,total);let cumulative=0;
 for(let index=0;index<weights.length;index++){cumulative+=weights[index];if(roll<cumulative)return index;}
 return 0;
}
export function originalEncodeBingoIndices(indices){
 let packed=0;for(let tier=0;tier<3;tier++){const value=indices[tier];const index=Number.isInteger(value)&&value>=0&&value<3?value:0;packed|=index<<(tier*8);}return packed>>>0;
}
export function originalDecodeBingoIndices(packed){const value=Number(packed)>>>0;return[0,8,16].map(shift=>(value>>>shift)&255);}
function rowFor(dex){const row=SOURCE_BINGO_DATA[Number(dex)-1];if(!row)throw new RangeError('Source bingo dex must be 1..151');return row;}
export function originalSelectBingo(dex,rangeInt){const row=rowFor(dex);const indices=[1,2,3].map(tier=>originalLotteryBingoIndex(row['m_weights_'+tier],rangeInt));return{version:1,indices,packed:originalEncodeBingoIndices(indices)};}
export function originalBingoEffects(dex,packed){
 const row=rowFor(dex),indices=originalDecodeBingoIndices(packed),facts=SPECIES_FACTS[String(dex).padStart(3,'0')];
 return indices.map((index,tier)=>{if(index>=3)throw new RangeError('Invalid persisted source bingo index');const suffix=tier+1;return{tier:suffix,index,commandID:row['m_commandIDs_'+suffix][index],params:[row['m_values_'+suffix+'_1'][index],row['m_values_'+suffix+'_2'][index]],weight:row['m_weights_'+suffix][index],text:facts.bingos[tier][index]};});
}
export function originalBingoTexts(dex,packed){return originalBingoEffects(dex,packed).map(effect=>effect.text);}
export function originalMigrateBingoTexts(dex,texts){
 rowFor(dex);const facts=SPECIES_FACTS[String(dex).padStart(3,'0')],indices=texts.slice(0,3).map((text,tier)=>facts.bingos[tier].indexOf(text));
 const unresolved=[0,1,2].filter(tier=>indices[tier]===undefined||indices[tier]<0);
 if(unresolved.length)return{resolved:false,unresolved,originalTexts:[...texts]};
 return{resolved:true,version:1,indices,packed:originalEncodeBingoIndices(indices)};
}
